-- Sync current detailed service page cards into CMS template fields.
-- Keeps the frontend layout fixed while allowing admins to edit text, images, cards, FAQ and ordering from the backend.

insert into public.page_template_fields (
  page_slug, template_key, field_key, field_label, field_type, text_value, json_value, sort_order, help_text
)
values
  ('home-care', 'service_page', 'feature_cards', '重點特色卡', 'json', null, '[{"label":"01","title":"把需求講清楚","body":"先釐清長輩目前最困擾的生活情境，例如洗澡、如廁、移位、用餐、出院返家或白天無人陪伴。"},{"label":"02","title":"把服務排穩定","body":"依照區域、時段、照顧強度與長輩個性安排照顧服務員，讓家庭不是每次都重新適應。"},{"label":"03","title":"把紀錄留完整","body":"服務後整理照顧紀錄、狀態變化與提醒事項，讓家屬知道今天發生什麼，也知道下一步要注意什麼。"},{"label":"04","title":"把品質追到底","body":"督導定期回訪、檢視服務內容與家屬回饋，讓照顧不是有人到場而已，而是有人持續負責。"}]'::jsonb, 300, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('home-care', 'service_page', 'pain_points', '家庭痛點卡', 'json', null, '[{"title":"剛出院返家","body":"床邊起身、輪椅轉位、沐浴動線、用餐狀態都需要重新安排，家屬常常不知道第一週該怎麼做。"},{"title":"白天沒人在家","body":"家屬上班後最擔心跌倒、忘記吃飯、情緒低落或臨時狀況無人協助。"},{"title":"失智照顧壓力","body":"反覆詢問、作息混亂、抗拒洗澡或外出，需要有耐心且能理解行為背後需求的陪伴。"},{"title":"照顧者太累","body":"長期照顧容易累積睡眠不足、情緒壓力與家庭摩擦，需要喘息，也需要有人一起分擔。"},{"title":"不知道服務品質","body":"只知道有人來，卻不清楚今天做了什麼、長輩狀態有沒有變化、是否需要調整服務。"},{"title":"家人意見不同","body":"每位家屬對照顧期待不同，歲悅會協助把需求、服務範圍與回報方式說清楚。"}]'::jsonb, 301, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('home-care', 'service_page', 'scene_cards', '服務情境圖卡', 'json', null, '[{"image":"assets/homecare-detail-01-greeting-fast.jpg","title":"進門先看見人","body":"服務員進門後先問候、觀察精神與情緒，讓長輩知道今天不是被處理，而是被陪伴。"},{"image":"assets/homecare-detail-02-care-plan-fast.jpg","title":"家屬與督導一起排照顧","body":"把服務目標、時段、禁忌、回報方式與家屬最在意的事情寫進計畫裡。"},{"image":"assets/homecare-detail-03-safe-transfer-fast.jpg","title":"安全移動不靠硬撐","body":"協助起身、移位、陪同走動時，用合適步調與支撐方式降低跌倒風險。"},{"image":"assets/homecare-detail-04-daily-support-fast.jpg","title":"日常細節也要被記得","body":"備餐、用餐觀察、生活提醒與照顧紀錄，讓家裡的照顧變得清楚可追蹤。"}]'::jsonb, 302, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('home-care', 'service_page', 'service_items', '服務內容卡', 'json', null, '[{"title":"身體照顧","body":"沐浴、穿脫衣物、如廁、移位、翻身、拍背、用餐協助。","fit":"適合出院返家、行動不便、需協助盥洗或日常照顧者。"},{"title":"生活照顧","body":"備餐、陪伴、簡易環境整理、代購、陪同外出與生活提醒。","fit":"適合獨居、白天家人不在、需要日常支持的長輩。"},{"title":"陪同就醫","body":"陪同掛號、候診、拿藥、交通動線提醒與回家後重點回報。","fit":"適合家屬無法請假，或長輩外出需要有人陪同者。"},{"title":"喘息支持","body":"短時段接手照顧，讓主要照顧者能休息、辦事、上班或恢復生活。","fit":"適合長期照顧壓力高、需要固定喘息時段的家庭。"},{"title":"失智陪伴","body":"用穩定語氣、生活線索與熟悉活動陪伴，降低焦躁與抗拒。","fit":"適合有認知退化、作息混亂或需要耐心引導的長輩。"},{"title":"安全觀察","body":"觀察跌倒風險、進食飲水、精神變化、皮膚狀況與居家動線。","fit":"適合希望及早發現風險並調整環境的家庭。"},{"title":"家屬回報","body":"服務紀錄、照片回報、異常提醒、家屬溝通與督導追蹤。","fit":"適合想掌握照顧品質、需要清楚資訊的家屬。"},{"title":"資源銜接","body":"協助家屬理解長照資源、日照、復能、輔具與其他服務銜接。","fit":"適合剛開始接觸長照、不確定該怎麼安排的家庭。"}]'::jsonb, 303, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('home-care', 'service_page', 'scenario_cards', '使用情境卡', 'json', null, '[{"title":"出院返家第一週","body":"協助家屬把床邊、浴室、用餐、服藥提醒與移位方式重新整理，降低返家初期的混亂。","tag":"重點：安全動線、照顧教學、服務銜接"},{"title":"白天獨居陪伴","body":"固定到宅確認長輩狀態、協助備餐與生活提醒，讓家屬在上班時也能安心。","tag":"重點：陪伴、飲食、狀態回報"},{"title":"失智長輩支持","body":"用熟悉節奏陪伴盥洗、進食、活動與情緒安撫，降低家屬每天溝通拉扯。","tag":"重點：耐心引導、穩定作息、情緒支持"},{"title":"主要照顧者喘息","body":"由照顧服務員在固定時段接手，讓家屬能補眠、外出、工作或照顧自己。","tag":"重點：短時接手、穩定交班、家屬支持"}]'::jsonb, 304, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('home-care', 'service_page', 'quality_cards', '品質系統卡', 'json', null, '[{"title":"媒合不是只看地點","body":"同時評估服務時段、長輩個性、照顧強度與照服員經驗，降低不適配機率。"},{"title":"服務前有交代","body":"把注意事項、服務範圍、禁忌與家屬期待先交代清楚，避免現場靠猜。"},{"title":"服務後有紀錄","body":"服務內容、長輩狀態、特殊狀況與下次提醒都會留下紀錄，讓家屬可追蹤。"},{"title":"督導會回頭看","body":"不是派案後就結束，督導會依回饋調整服務內容，讓品質能一路維持。"},{"title":"異常要被提醒","body":"跌倒風險、食慾改變、情緒變化、皮膚狀況或居家安全問題，都會提醒家屬。"},{"title":"跨服務可銜接","body":"若長輩後續需要日照、護理復能、輔具或其他資源，可協助整理下一步。"}]'::jsonb, 305, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('home-care', 'service_page', 'flow_cards', '服務流程卡', 'json', null, '[{"step":"01","title":"需求諮詢","body":"先了解長輩生活能力、疾病狀態、照顧困難、服務區域、希望時段與家屬期待。"},{"step":"02","title":"到宅或電話評估","body":"整理服務目標、風險提醒、可提供項目與目前最需要優先處理的照顧問題。"},{"step":"03","title":"照顧計畫建立","body":"把服務內容、注意事項、回報方式、家屬溝通窗口與可能變動狀況寫清楚。"},{"step":"04","title":"照服員媒合","body":"依照地區、時段、照顧強度與長輩特性安排合適人員，必要時由督導協助銜接。"},{"step":"05","title":"正式到宅服務","body":"服務員依計畫執行照顧，並在現場觀察長輩狀態與家庭環境變化。"},{"step":"06","title":"紀錄與追蹤","body":"服務後回報重點，督導依家屬回饋與長輩變化調整服務，讓照顧走得久。"}]'::jsonb, 306, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('home-care', 'service_page', 'faq_items', '常見問答', 'json', null, '[{"question":"居家照顧一定要每天使用嗎？","answer":"不一定。可以依家庭需求安排固定時段、短時喘息、陪同就醫或階段性服務，重點是先把需求與可安排區域確認清楚。"},{"question":"家屬不在家也可以服務嗎？","answer":"可以，但服務開始前會先確認進出方式、聯絡窗口、緊急狀況處理與回報方式，讓責任界線清楚。"},{"question":"可以協助失智長輩嗎？","answer":"可以。會依長輩的習慣、情緒觸發點、溝通方式與安全風險安排服務內容，並提醒家屬需要一起配合的地方。"},{"question":"如果照顧服務員不適合怎麼辦？","answer":"歲悅會先了解不適合的原因，包含服務內容、溝通方式、時段或照顧強度，再由督導協助調整。"},{"question":"服務內容可以中途調整嗎？","answer":"可以。長輩狀態會變，家庭需求也會變，因此會透過紀錄與回饋逐步調整服務重點。"},{"question":"目前服務區域有哪些？","answer":"目前以臺北市、新北市與桃園部分區域為主，實際可服務範圍會依人力、時段與照顧需求確認。"}]'::jsonb, 307, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('day-care', 'service_page', 'feature_cards', '重點特色卡', 'json', null, '[{"label":"01","title":"白天有安全場域","body":"讓長輩離開長時間獨處的狀態，在有人看見、有人陪伴、有人觀察的環境中度過白天。"},{"label":"02","title":"生活節奏被重新建立","body":"用報到、量測、活動、共餐、午休與回家準備，讓長輩每天有穩定節奏與期待。"},{"label":"03","title":"活動不是填時間","body":"透過伸展、肌力、認知、手作、音樂與團體互動，讓長輩保有參與感與生活功能。"},{"label":"04","title":"家屬也能喘口氣","body":"白天照顧由團隊接手，讓主要照顧者能工作、休息與處理生活，同時仍能掌握長輩狀態。"}]'::jsonb, 308, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('day-care', 'service_page', 'pain_points', '家庭痛點卡', 'json', null, '[{"title":"白天一個人在家","body":"家屬上班後最擔心長輩跌倒、忘記吃飯、久坐不動或突然身體不舒服。"},{"title":"在家越來越少活動","body":"長輩如果缺少外出與互動，身體功能、食慾、情緒與睡眠常會一起下降。"},{"title":"家屬無法長期請假","body":"照顧不是一天兩天，家屬需要一個可以穩定銜接白天照顧的服務場域。"},{"title":"長輩抗拒陌生環境","body":"第一次去日照中心常會緊張，因此需要熟悉、試讀、陪伴與逐步建立安全感。"},{"title":"不知道白天過得如何","body":"家屬需要知道長輩今天吃得好不好、活動狀態如何、精神與情緒是否有變化。"},{"title":"照顧壓力持續累積","body":"主要照顧者若沒有喘息，長期下來容易疲乏，也會影響家庭關係與照顧品質。"}]'::jsonb, 309, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('day-care', 'service_page', 'scene_cards', '服務情境圖卡', 'json', null, '[{"image":"assets/daycare-detail-01-exercise-fast.jpg","title":"團體活動讓身體醒過來","body":"用安全、可跟上的節奏帶領伸展與律動，讓長輩重新感覺自己仍然能動。"},{"image":"assets/daycare-detail-02-meal-fast.jpg","title":"共餐不是吃飯而已","body":"餐食照顧會觀察食慾、吞嚥、飲水與情緒，也讓長輩在陪伴中用餐。"},{"image":"assets/daycare-detail-03-activity-fast.jpg","title":"手作與認知活動","body":"透過簡單任務、顏色、記憶與互動，讓活動成為長輩有成就感的時刻。"},{"image":"assets/daycare-detail-04-checkin-fast.jpg","title":"早晨報到與家屬交接","body":"從進門問候與健康觀察開始，讓家屬知道今天有人接住長輩。"}]'::jsonb, 310, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('day-care', 'service_page', 'service_items', '服務內容卡', 'json', null, '[{"title":"生活照顧","body":"報到接待、健康觀察、如廁協助、午休照顧、回家準備與安全巡視。","fit":"適合白天需要陪伴、提醒與基本生活支持的長輩。"},{"title":"餐食照顧","body":"共餐、飲水提醒、用餐觀察、吞嚥風險提醒與營養狀態初步留意。","fit":"適合食慾下降、容易忘記吃飯或需要用餐陪伴者。"},{"title":"健康促進","body":"椅上運動、伸展、肌力、平衡、律動、認知刺激與生活功能活動。","fit":"適合希望維持活動量、延緩退化與增加生活刺激者。"},{"title":"社交陪伴","body":"團體活動、節慶活動、手作課程、音樂互動與同儕交流。","fit":"適合在家較少出門、情緒低落或需要人際互動者。"},{"title":"失智友善支持","body":"用熟悉節奏、環境提示、活動引導與安全陪伴，降低焦躁與不安。","fit":"適合輕中度失智、需要白天規律活動與陪伴者。"},{"title":"家屬回報","body":"出席狀況、用餐活動、精神情緒、特殊事件與照顧建議回饋。","fit":"適合希望知道長輩白天過得如何的家庭。"},{"title":"交通與接送提醒","body":"依實際服務條件協助討論交通安排、接送注意事項與到離場交接。","fit":"適合家屬上班時間不易親自接送者。"},{"title":"資源銜接","body":"協助家屬理解長照資源、居家照顧、復能、課程與家庭支持方案。","fit":"適合照顧需求可能逐步變化的家庭。"}]'::jsonb, 311, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('day-care', 'service_page', 'scenario_cards', '使用情境卡', 'json', null, '[{"title":"家屬白天要上班","body":"長輩白天到中心參與活動、用餐與休息，家屬能安心工作，晚上再回到熟悉的家。","tag":"重點：白天托顧、家屬喘息、規律回報"},{"title":"長輩在家越來越少動","body":"透過團體律動、伸展、手作與社交互動，讓長輩重新建立活動量與生活期待。","tag":"重點：活動參與、功能維持、生活刺激"},{"title":"失智長輩需要規律","body":"用固定流程、熟悉人員、活動提示與友善環境，降低不安與抗拒。","tag":"重點：熟悉節奏、情緒安撫、安全觀察"},{"title":"出院後需要白天支持","body":"日照能承接白天活動、餐食、休息與觀察，搭配家屬與居家資源一起穩定恢復。","tag":"重點：照顧銜接、體力恢復、家庭支持"}]'::jsonb, 312, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('day-care', 'service_page', 'quality_cards', '品質系統卡', 'json', null, '[{"title":"到離場都有觀察","body":"從報到、量測、精神狀態到離場準備，都會留意長輩今天是否和平常不同。"},{"title":"活動設計有目的","body":"每一類活動都對應到身體、認知、情緒、社交或生活功能，不只是讓時間過去。"},{"title":"餐食狀況要被看見","body":"用餐速度、食慾、飲水、吞嚥與精神變化，都可能是照顧調整的重要線索。"},{"title":"交班回報要清楚","body":"團隊內部交班與對家屬回報能銜接，避免重要狀況只停留在某個人腦中。"},{"title":"家屬意見會被整理","body":"家屬的擔心、長輩回家後的狀態與服務建議，都會回到照顧調整。"},{"title":"跨服務能銜接","body":"當長輩需要居家照顧、護理復能、課程或其他資源時，可協助家屬整理下一步。"}]'::jsonb, 313, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('day-care', 'service_page', 'flow_cards', '服務流程卡', 'json', null, '[{"step":"01","title":"電話諮詢","body":"了解長輩身體狀態、認知情形、生活習慣、交通需求與家屬最擔心的問題。"},{"step":"02","title":"預約參觀","body":"讓家屬與長輩實際看見空間、活動安排、照顧人員與一日作息。"},{"step":"03","title":"初步評估","body":"整理照顧風險、活動能力、用餐需求、情緒反應與適合參與的活動節奏。"},{"step":"04","title":"試讀熟悉","body":"讓長輩慢慢熟悉環境與人員，降低第一次進入陌生場域的不安。"},{"step":"05","title":"穩定出席","body":"依照出席頻率、活動參與、餐食與精神狀態，調整照顧安排。"},{"step":"06","title":"家屬回報","body":"把每日重要觀察與建議回饋給家屬，必要時連結其他照顧資源。"}]'::jsonb, 314, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('day-care', 'service_page', 'faq_items', '常見問答', 'json', null, '[{"question":"日間照顧和居家照顧差在哪裡？","answer":"日間照顧是白天到中心接受照顧、活動、共餐與休息；居家照顧則是照顧服務員到家裡協助。兩者可以依家庭需求搭配。"},{"question":"長輩不想去陌生地方怎麼辦？","answer":"可以先參觀、短時間試讀或由家屬陪同熟悉。重點不是強迫長輩接受，而是慢慢建立安全感。"},{"question":"日照中心一天會做什麼？","answer":"通常會包含報到觀察、量測、活動、共餐、午休、下午活動、點心與回家準備，實際安排會依中心與長輩狀態調整。"},{"question":"家屬可以知道長輩白天狀態嗎？","answer":"可以。日照會回報出席、活動、餐食、精神狀況與特殊事件，讓家屬知道白天照顧重點。"},{"question":"失智長輩適合日照嗎？","answer":"許多失智長輩適合規律的日間照顧，但仍要依行為狀態、安全風險與中心照顧量能評估。"},{"question":"如果只想先體驗可以嗎？","answer":"可以先預約參觀或討論試讀安排，讓長輩與家屬確認環境、活動與照顧方式是否合適。"}]'::jsonb, 315, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('nursing', 'service_page', 'feature_cards', '重點特色卡', 'json', null, '[{"label":"01","title":"看見身體變化","body":"護理觀察不是只量數字，而是把血壓、食慾、睡眠、皮膚、傷口、用藥與精神狀態放回生活脈絡裡判斷。"},{"label":"02","title":"把能力練回生活","body":"復能不是做漂亮動作，而是讓長輩能更安全地起身、移位、走路、用餐、洗澡與參與日常。"},{"label":"03","title":"讓家屬學會方法","body":"把移位、翻身、跌倒預防、居家動線、用餐姿勢與照顧觀察教給家屬和照顧者。"},{"label":"04","title":"跨專業一起追蹤","body":"護理、治療、督導、照服員與家庭用同一套紀錄理解狀態，避免每個人各說各話。"}]'::jsonb, 316, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('nursing', 'service_page', 'pain_points', '家庭痛點卡', 'json', null, '[{"title":"出院後不敢動","body":"長輩回家後常因怕跌倒、怕痛、怕麻煩而越來越少活動，能力反而退得更快。"},{"title":"家屬不知道怎麼扶","body":"起身、移位、洗澡、上廁所都怕出事，照顧者常用蠻力撐，長期下來人也受傷。"},{"title":"健康數字看不懂","body":"血壓、食慾、睡眠、傷口、精神狀態出現變化時，家屬不知道哪些需要注意、哪些需要就醫。"},{"title":"居家環境有風險","body":"浴室濕滑、床邊動線、椅子高度、夜間照明與門檻，都可能讓長輩跌倒或不敢活動。"},{"title":"訓練無法延續","body":"在專業人員面前做得到，回家卻不知道怎麼練、練多久、什麼狀況要停止。"},{"title":"照顧者缺少回饋","body":"家屬、移工或照服員每天都在照顧，但很少有人回頭看方法是否正確、是否需要調整。"}]'::jsonb, 317, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('nursing', 'service_page', 'scene_cards', '服務情境圖卡', 'json', null, '[{"image":"assets/nursing-detail-01-vitals-clear.jpg","title":"護理觀察與健康量測","body":"從血壓、精神、食慾與日常變化看見風險，讓家屬知道什麼需要注意。"},{"image":"assets/nursing-detail-02-walking-clear.jpg","title":"步行與移位練習","body":"復能不是催促長輩，而是用安全步調陪他一步一步重新找回把握。"},{"image":"assets/nursing-detail-03-home-safety-fast.jpg","title":"居家安全與家屬教學","body":"把浴室、床邊、動線與扶手配置說清楚，降低家庭照顧的意外風險。"},{"image":"assets/nursing-detail-04-care-plan-fast.jpg","title":"跨專業目標討論","body":"護理、治療、照顧與家屬一起確認目標，讓練習回到真實生活。"}]'::jsonb, 318, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('nursing', 'service_page', 'service_items', '服務內容卡', 'json', null, '[{"title":"健康狀態追蹤","body":"血壓、食慾、睡眠、排泄、皮膚、傷口、用藥與精神狀態觀察。","fit":"適合出院返家、慢性病、身體狀況不穩或家屬需要判斷指引者。"},{"title":"復能訓練支持","body":"坐站、移位、步行、平衡、肌力、耐力與日常生活動作練習。","fit":"適合希望恢復活動能力、降低臥床與維持生活自理者。"},{"title":"居家安全建議","body":"床邊動線、浴室安全、扶手、照明、門檻、椅高與防滑配置建議。","fit":"適合有跌倒風險、家中動線不順或家屬擔心意外者。"},{"title":"照顧技巧教學","body":"移位、翻身、拍背、沐浴安全、陪走、用餐姿勢與日常觀察方法。","fit":"適合家屬、移工、照服員共同照顧，需要統一方法的家庭。"},{"title":"復能目標設計","body":"把專業訓練拆成生活目標，例如安全走到浴室、自己坐起、穩定用餐。","fit":"適合不想只做訓練，而想改善真正生活場景的長輩。"},{"title":"營養與吞嚥提醒","body":"觀察食慾、飲水、吞嚥、餐具姿勢與用餐疲累狀況，提供照顧提醒。","fit":"適合用餐速度變慢、容易嗆咳、食慾下降或體力不足者。"},{"title":"照顧紀錄與回報","body":"整理每次觀察、練習內容、家屬提醒、風險變化與後續建議。","fit":"適合需要多人協作、希望照顧資訊透明可追蹤的家庭。"},{"title":"跨服務銜接","body":"依需求銜接居家照顧、日間照顧、輔具資源、課程或家庭照顧支持。","fit":"適合需求變化快、需要整合不同服務的家庭。"}]'::jsonb, 319, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('nursing', 'service_page', 'scenario_cards', '使用情境卡', 'json', null, '[{"title":"出院返家後體力下降","body":"協助家屬理解哪些活動可以練、哪些要避免，並把復能目標拆回日常生活。","tag":"重點：返家銜接、體力恢復、安全活動"},{"title":"跌倒後不敢走","body":"透過步行、平衡、坐站與環境調整，陪長輩慢慢恢復移動信心。","tag":"重點：跌倒預防、步態安全、心理支持"},{"title":"家屬照顧方法不一致","body":"把移位、翻身、陪走、沐浴與用餐方法統一，降低家屬與照顧者之間的落差。","tag":"重點：家庭教學、照顧一致性、風險降低"},{"title":"慢性病與功能退化並存","body":"同時追蹤健康狀態與生活功能，避免只看疾病數字，卻忽略長輩每天能不能生活。","tag":"重點：護理觀察、復能支持、生活功能"}]'::jsonb, 320, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('nursing', 'service_page', 'quality_cards', '品質系統卡', 'json', null, '[{"title":"先評估再練習","body":"每一次復能都要先看精神、疼痛、血壓、活動能力與安全風險，不是直接開始訓練。"},{"title":"目標要回到生活","body":"復能目標不是只看步數或肌力，而是能不能安全起身、走到廁所、坐穩吃飯。"},{"title":"家屬要學得會","body":"專業人員做得到不夠，家屬與照顧者也要理解怎麼做、何時停止、何時求助。"},{"title":"環境要一起調整","body":"如果床、椅、浴室、照明與動線不安全，再多訓練都可能被居家風險抵消。"},{"title":"紀錄要能追蹤","body":"每次練習內容、身體反應、風險提醒與下次目標都要留下來，讓照顧能延續。"},{"title":"跨專業要對齊","body":"護理、治療、督導、照服員與家屬需要用同一套目標說話，才不會互相抵消。"}]'::jsonb, 321, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('nursing', 'service_page', 'flow_cards', '服務流程卡', 'json', null, '[{"step":"01","title":"需求諮詢","body":"了解長輩疾病史、近期變化、出院狀態、跌倒經驗、家屬擔心與生活目標。"},{"step":"02","title":"護理與功能評估","body":"整理健康狀態、活動能力、用藥、疼痛、居家環境與照顧者能力。"},{"step":"03","title":"目標設定","body":"把復能目標拆成小步驟，例如安全起身、穩定步行、自己用餐或到浴室。"},{"step":"04","title":"到宅或場域支持","body":"由專業人員陪同練習，並同步教家屬與照顧者日常照顧方法。"},{"step":"05","title":"居家環境調整","body":"依實際動線提出扶手、防滑、照明、床椅高度與輔具使用建議。"},{"step":"06","title":"追蹤與轉介","body":"依紀錄與回饋調整訓練強度，必要時銜接醫療、輔具、居家或日照服務。"}]'::jsonb, 322, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('nursing', 'service_page', 'faq_items', '常見問答', 'json', null, '[{"question":"護理復能和一般復健有什麼不同？","answer":"護理復能更重視生活場景、居家風險、照顧者教學與日常延續，不只是在場域中完成訓練動作。"},{"question":"長輩很虛弱也可以做復能嗎？","answer":"可以先從安全評估、姿勢調整、床邊活動、坐站或低強度練習開始，重點是依狀態安排，不勉強。"},{"question":"家屬需要一起學嗎？","answer":"非常建議。復能真正有效的關鍵，是家屬與照顧者在每天生活中能用正確方式陪伴。"},{"question":"可以協助居家安全建議嗎？","answer":"可以。會從浴室、床邊、走道、照明、門檻、椅高與常用物品位置看起，協助降低跌倒與移位風險。"},{"question":"服務會留下紀錄嗎？","answer":"會。每次服務會整理觀察、練習內容、身體反應與後續提醒，讓家庭與團隊能持續追蹤。"},{"question":"護理復能可以和居家照顧搭配嗎？","answer":"可以。復能人員設定方法與目標後，居家照顧服務員與家屬可以在日常中協助延續。"}]'::jsonb, 323, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('migrant-training', 'service_page', 'feature_cards', '重點特色卡', 'json', null, '[{"label":"01","title":"把技能教到能做","body":"翻身、移位、沐浴、如廁、用餐、陪走與拍背都要拆成看得懂、練得會、回家後做得出來的步驟。"},{"label":"02","title":"把溝通變成共同語言","body":"協助移工理解家屬期待、長輩情緒、每日回報與突發狀況處理，降低誤會。"},{"label":"03","title":"把安全放進每個動作","body":"跌倒預防、感染控制、用藥提醒、營養觀察、環境安全與緊急狀況都要能被實作。"},{"label":"04","title":"把訓練延續到家庭","body":"課後可搭配督導回饋、家屬諮詢、複訓安排與照顧紀錄，讓技巧真的進到日常。"}]'::jsonb, 324, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('migrant-training', 'service_page', 'pain_points', '家庭痛點卡', 'json', null, '[{"title":"移工聽過但不會做","body":"很多課程停留在聽講，回到家面對洗澡、移位、餵食、情緒抗拒時仍不知道如何操作。"},{"title":"家屬交代不清楚","body":"家屬常用自己的經驗交代事情，但沒有把優先順序、禁忌、回報方式與緊急處理說成共同語言。"},{"title":"長輩拒絕照顧","body":"移工需要理解長輩為什麼抗拒，也要學會用合適語氣、順序與情境引導，而不是硬做。"},{"title":"安全動作不穩定","body":"翻身、移位、扶走、沐浴和用餐是高風險情境，只要姿勢錯，長輩和照顧者都可能受傷。"},{"title":"文化與語言有落差","body":"家庭期待、長輩習慣、照顧價值和回報方式不同，若沒有演練，很容易累積摩擦。"},{"title":"訓練後沒有人追蹤","body":"如果課後沒有回饋與複訓，學到的技巧很容易在真實家庭壓力中變形。"}]'::jsonb, 325, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('migrant-training', 'service_page', 'scene_cards', '服務情境圖卡', 'json', null, '[{"image":"assets/migrant-detail-01-classroom-fast.jpg","title":"課堂示範與分組練習","body":"把照顧技能拆成步驟，讓移工不只聽懂，也能實際操作。"},{"image":"assets/migrant-detail-02-transfer-fast.jpg","title":"安全移位實作","body":"床到輪椅、翻身與扶走都要反覆演練，降低長輩與照顧者受傷風險。"},{"image":"assets/migrant-detail-03-meal-fast.jpg","title":"餐食與營養照顧","body":"從備餐、吞嚥、餵食姿勢到飲水提醒，讓日常照顧更細緻。"},{"image":"assets/migrant-detail-04-communication-fast.jpg","title":"家庭溝通情境演練","body":"透過角色扮演練習每日回報、家屬交代與長輩抗拒照顧的處理。"}]'::jsonb, 326, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('migrant-training', 'service_page', 'service_items', '服務內容卡', 'json', null, '[{"title":"基礎身體照顧","body":"翻身、拍背、移位、沐浴、如廁、穿脫衣物、陪走與床邊照顧。","fit":"適合剛到家庭服務或需要建立基礎照顧技巧的移工。"},{"title":"安全移位與防跌","body":"床到輪椅、椅到站立、浴室動線、扶走姿勢、跌倒預防與輔具使用。","fit":"適合家中長輩行動不穩、跌倒風險高或照顧者常用蠻力者。"},{"title":"餐食與營養觀察","body":"備餐、軟質餐、飲水提醒、餵食姿勢、吞嚥觀察、食慾與體重變化。","fit":"適合長輩食慾下降、吞嚥不順或家屬擔心營養不足者。"},{"title":"失智與情緒照顧","body":"重複詢問、抗拒洗澡、日夜顛倒、情緒不安與熟悉線索引導。","fit":"適合照顧認知退化、失智症或情緒起伏較大的長輩。"},{"title":"家庭溝通與回報","body":"家屬交代、每日回報、異常提醒、照片紀錄、照顧邊界與衝突處理。","fit":"適合家庭溝通容易卡住、照顧分工不清或期待不同者。"},{"title":"衛教與感染控制","body":"手部衛生、口腔清潔、皮膚觀察、傷口提醒、感染預防與用藥安全。","fit":"適合慢性病、臥床、皮膚脆弱或需長期照顧的家庭。"},{"title":"突發狀況處理","body":"跌倒、嗆咳、發燒、意識改變、呼吸不適與緊急聯絡流程。","fit":"適合需要建立家庭緊急處理 SOP 的雇主與照顧者。"},{"title":"證書與複訓","body":"課程紀錄、完訓證明、技能回饋、複訓安排與督導建議。","fit":"適合企業、家庭或仲介單位安排系統化訓練。"}]'::jsonb, 327, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('migrant-training', 'service_page', 'scenario_cards', '使用情境卡', 'json', null, '[{"title":"新聘移工剛到家","body":"先建立基礎照顧方法、家庭規則、長輩習慣與每日回報方式，降低磨合期混亂。","tag":"重點：基礎技能、家庭交接、日常回報"},{"title":"家中有高風險動作","body":"針對移位、洗澡、如廁、扶走與床邊照顧反覆演練，避免照顧者與長輩一起受傷。","tag":"重點：安全移位、防跌、照顧者保護"},{"title":"長輩有失智或抗拒照顧","body":"透過情境演練理解行為背後需求，學習非強迫式溝通、環境提示與活動引導。","tag":"重點：失智友善、情緒安撫、溝通引導"},{"title":"雇主想建立一致照顧標準","body":"把家庭禁忌、服務期待、回報方式、緊急流程與照顧紀錄整理成共同規則。","tag":"重點：雇主溝通、流程標準、照顧紀錄"}]'::jsonb, 328, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('migrant-training', 'service_page', 'quality_cards', '品質系統卡', 'json', null, '[{"title":"先看照顧場景","body":"課程不是套版教材，會先理解長輩狀態、家庭環境、移工語言能力與家屬期待。"},{"title":"示範後要實作","body":"每個動作都要從老師示範進到學員練習，才知道回家後能不能真的做。"},{"title":"錯誤動作要修正","body":"訓練現場會看姿勢、力道、站位、語氣與流程，避免錯誤技巧被帶回家庭。"},{"title":"回報方式要一致","body":"家屬需要知道移工每天該回報什麼，移工也要知道哪些狀況不能自己判斷。"},{"title":"語言文化要被考慮","body":"用圖像、示範、簡單語句與角色扮演降低理解落差，讓課程更接近真實家庭。"},{"title":"課後要能追蹤","body":"透過複訓、督導建議與家屬諮詢，讓培訓效果能持續延伸到照顧現場。"}]'::jsonb, 329, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('migrant-training', 'service_page', 'flow_cards', '服務流程卡', 'json', null, '[{"step":"01","title":"確認家庭情境","body":"了解照顧對象狀態、家庭規則、移工語言能力、照顧困難與最需要補強的技能。"},{"step":"02","title":"設計課程模組","body":"依需求組合基礎照顧、安全移位、餐食營養、失智陪伴、溝通回報與衛教安全。"},{"step":"03","title":"示範與分解","body":"由講師把每個照顧動作拆解成順序、站位、提醒語與注意事項。"},{"step":"04","title":"實作與角色演練","body":"透過分組練習、情境演練與即時修正，確認學員不是只聽懂。"},{"step":"05","title":"家屬共識整理","body":"把家屬期待、禁忌、回報方式、緊急流程與照顧紀錄整理成可執行規則。"},{"step":"06","title":"訓後回饋與複訓","body":"課後提供重點回饋，必要時安排複訓、督導諮詢或家庭照顧建議。"}]'::jsonb, 330, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('migrant-training', 'service_page', 'faq_items', '常見問答', 'json', null, '[{"question":"移工培訓可以客製化嗎？","answer":"可以。可以依長輩狀態、家庭環境、移工語言能力與雇主期待，安排不同課程模組。"},{"question":"家屬需要一起上課嗎？","answer":"建議家屬至少參與需求確認或重點回饋，因為照顧標準與回報方式需要家庭一起對齊。"},{"question":"課程會有實作嗎？","answer":"會。移位、翻身、餵食、沐浴安全、溝通情境等都會用示範與演練確認學員理解。"},{"question":"適合剛來台灣的移工嗎？","answer":"適合。課程會盡量用圖像、示範、簡單語句與實作降低理解門檻。"},{"question":"可以提供完訓證明嗎？","answer":"可以依課程規劃提供課程紀錄或完訓證明，適合家庭、企業或合作單位留存。"},{"question":"如果課後在家還是遇到問題怎麼辦？","answer":"可再安排複訓、督導諮詢或家庭照顧建議，把實際問題帶回課程調整。"}]'::jsonb, 331, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('quality', 'service_page', 'feature_cards', '重點特色卡', 'json', null, '[{"label":"01","title":"把經驗整理成教材","body":"第一線的好做法不能只留在資深人員身上，要轉成教材、流程、案例與檢核表。"},{"label":"02","title":"把新人帶進標準","body":"新人不只需要知道工作內容，更要理解歲悅的照顧語言、服務邊界、紀錄方式與家屬溝通。"},{"label":"03","title":"把紀錄變成品質線索","body":"服務紀錄不是行政作業，而是看見風險、追蹤改善與判斷訓練需求的重要依據。"},{"label":"04","title":"把問題轉成改善","body":"品管不是抓錯，而是把家屬回饋、異常事件與現場困難轉成下一次更穩的流程。"}]'::jsonb, 332, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('quality', 'service_page', 'pain_points', '家庭痛點卡', 'json', null, '[{"title":"好服務靠個人經驗","body":"如果服務品質只靠資深人員提醒，新人一多、據點一多，做法就容易不一致。"},{"title":"訓練上完就忘","body":"課程如果沒有對應現場情境、紀錄檢核與督導回饋，學到的內容很難落地。"},{"title":"紀錄寫了但沒被用","body":"服務紀錄若只是留存，沒有被回看、分析與轉成行動，就無法真的改善品質。"},{"title":"家屬回饋沒有閉環","body":"家屬提出問題後，如果沒有處理狀態、改善責任與追蹤結果，信任就會流失。"},{"title":"跨部門資訊斷裂","body":"教育、督導、行政與現場如果各自處理問題，服務品質就很難累積成制度。"},{"title":"擴張時品質容易掉","body":"當服務量、據點與人員增加，如果沒有標準化中台支撐，品質落差會快速放大。"}]'::jsonb, 333, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('quality', 'service_page', 'scene_cards', '服務情境圖卡', 'json', null, '[{"image":"assets/quality-detail-01-materials-fast.jpg","title":"教材與流程整理","body":"把照顧現場的經驗整理成可學習、可複製、可追蹤的訓練資料。"},{"image":"assets/quality-detail-02-training-fast.jpg","title":"內部教育訓練","body":"訓練不是把人叫來上課，而是讓服務方法、語言與判斷更一致。"},{"image":"assets/quality-detail-03-audit-fast.jpg","title":"服務紀錄檢核","body":"從紀錄看見服務品質、照顧風險與需要再支持的現場問題。"},{"image":"assets/quality-detail-04-improvement-fast.jpg","title":"品質改善會議","body":"讓督導、教育與營運一起把問題轉成下一輪改善行動。"}]'::jsonb, 334, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('quality', 'service_page', 'service_items', '服務內容卡', 'json', null, '[{"title":"新人訓練制度","body":"品牌理念、服務倫理、照顧流程、紀錄規範、家屬溝通與異常回報。","fit":"適合新進照服員、督導、行政與跨部門新人。"},{"title":"在職訓練規劃","body":"失智照顧、移位安全、溝通技巧、風險辨識、服務紀錄與專題課程。","fit":"適合需要持續提升專業與一致做法的服務團隊。"},{"title":"服務標準建立","body":"照顧流程、紀錄格式、風險提醒、家屬回報、交班與異常處理標準。","fit":"適合擴張服務量或多據點營運時維持品質。"},{"title":"紀錄與稽核","body":"服務紀錄、督導訪視、家屬回饋、課程出席、異常事件與改善追蹤。","fit":"適合需要定期檢視服務穩定度與風險的單位。"},{"title":"案例討論會","body":"把真實照顧事件轉成案例，討論判斷、溝通、流程與下次可改善行動。","fit":"適合督導、照服員與教育品管共同學習。"},{"title":"家屬回饋管理","body":"整理家屬問題、處理狀態、責任分工、回覆內容與追蹤結果。","fit":"適合想建立信任閉環與客訴改善機制的團隊。"},{"title":"異常事件改善","body":"問題盤點、原因分析、改善方案、追蹤指標、回饋會議與再教育。","fit":"適合要把現場問題轉成制度改善的服務單位。"},{"title":"管理報表設計","body":"訓練覆蓋率、稽核完成率、缺失類型、改善進度與服務品質指標。","fit":"適合需要管理者快速掌握品質狀態的組織。"}]'::jsonb, 335, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('quality', 'service_page', 'scenario_cards', '使用情境卡', 'json', null, '[{"title":"新據點或新團隊建立","body":"先建立教材、流程、交班、紀錄與督導標準，避免團隊各做各的。","tag":"重點：新人訓練、SOP、服務標準"},{"title":"服務量快速增加","body":"用訓練、稽核與報表管理品質落差，讓擴張不犧牲服務穩定度。","tag":"重點：品質中台、稽核追蹤、管理報表"},{"title":"家屬回饋變多","body":"把問題分類、處理狀態、改善責任與回覆節奏建立起來，讓信任能被修復。","tag":"重點：回饋管理、客訴閉環、改善追蹤"},{"title":"現場問題反覆發生","body":"透過案例討論、原因分析與再教育，把重複問題轉成制度調整。","tag":"重點：案例討論、異常改善、再教育"}]'::jsonb, 336, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('quality', 'service_page', 'quality_cards', '品質系統卡', 'json', null, '[{"title":"教材要來自現場","body":"教材不是漂亮簡報，而是從服務紀錄、督導回饋、家屬問題與實際案例整理出來。"},{"title":"訓練要能被驗證","body":"上課不是結束，要看出席、測驗、演練、紀錄與服務表現是否真的改變。"},{"title":"稽核不是找麻煩","body":"稽核是為了看見風險與缺口，讓現場知道下一步怎麼修正。"},{"title":"改善要有負責人","body":"每個改善行動都要有責任人、期限、追蹤狀態與回看機制。"},{"title":"資料要回到管理","body":"訓練、紀錄、稽核、回饋與異常資料要能變成管理者看得懂的品質指標。"},{"title":"文化要支持學習","body":"品管要讓前線敢回報問題、願意討論案例，而不是害怕被責備。"}]'::jsonb, 337, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('quality', 'service_page', 'flow_cards', '服務流程卡', 'json', null, '[{"step":"01","title":"盤點品質議題","body":"整理服務紀錄、家屬回饋、督導觀察、異常事件與現場常見問題。"},{"step":"02","title":"建立標準與教材","body":"把議題轉成教材、流程、演練情境、檢核表與可追蹤指標。"},{"step":"03","title":"安排訓練與演練","body":"依職務、場域與服務類型安排新人訓練、在職課程與案例討論。"},{"step":"04","title":"執行紀錄檢核","body":"檢視服務紀錄、家屬回報、督導訪視與異常處理是否符合標準。"},{"step":"05","title":"召開改善會議","body":"跨部門討論原因、責任、改善方案與需要再教育的內容。"},{"step":"06","title":"追蹤改善成效","body":"定期回看訓練覆蓋率、問題類型、改善進度與服務品質變化。"}]'::jsonb, 338, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('quality', 'service_page', 'faq_items', '常見問答', 'json', null, '[{"question":"教育品管是在抓錯嗎？","answer":"不是。教育品管的目標是讓問題被看見、被討論、被改善，讓前線更有方法，而不是讓人害怕回報。"},{"question":"哪些人需要接受教育訓練？","answer":"照服員、督導、行政、課務、管理者都需要。不同角色會有不同訓練重點。"},{"question":"服務紀錄為什麼重要？","answer":"紀錄能看見長輩狀態、服務落差、家屬回饋與風險變化，是品質管理最重要的資料來源之一。"},{"question":"可以協助其他單位建立品管制度嗎？","answer":"可以依需求協助規劃教材、流程、稽核表、回饋機制與改善追蹤方式。"},{"question":"教育品管和後台 CMS 有關嗎？","answer":"有。文章、課程、檔案、表單、內容健康檢查與網站流量中心，都能成為管理與改善的一部分。"},{"question":"怎麼知道改善有沒有效？","answer":"需要設定指標，例如訓練完成率、稽核缺失改善率、家屬回饋處理時間與重複問題下降情形。"}]'::jsonb, 339, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('community', 'service_page', 'feature_cards', '重點特色卡', 'json', null, '[{"label":"01","title":"離家近的照顧入口","body":"讓長輩不用等到失能很嚴重才接觸長照，而是在生活圈裡就能開始參與活動、被看見與被提醒。"},{"label":"02","title":"預防延緩失能","body":"透過伸展、肌力、平衡、認知與社交活動，把預防照顧做在生活裡，而不是等問題發生才處理。"},{"label":"03","title":"家屬支持與諮詢","body":"據點也是家屬最容易開口詢問的地方，協助釐清長照資源、服務選擇與下一步安排。"},{"label":"04","title":"區域資源串聯","body":"把居家照顧、日間照顧、護理復能、家屬課程與社區活動串起來，讓照顧更貼近日常。"}]'::jsonb, 340, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('community', 'service_page', 'pain_points', '家庭痛點卡', 'json', null, '[{"title":"長輩不想出門","body":"在家待久了，活動量、食慾、社交互動與情緒都可能慢慢下降，需要一個熟悉且壓力低的出門理由。"},{"title":"家屬不知道去哪問","body":"很多家庭還不到需要大量服務，但已經開始擔心跌倒、失智、營養、用藥與照顧壓力。"},{"title":"社區資源太零散","body":"活動、課程、服務、補助與轉介常分散在不同窗口，家屬需要有人協助整理。"},{"title":"預防常被忽略","body":"長輩還能走、還能自理時，最適合透過活動維持功能，但這也是最容易被忽視的階段。"},{"title":"照顧者缺少同伴","body":"家屬在照顧路上常覺得孤單，據點能提供課程、交流與被理解的空間。"},{"title":"需要更早發現變化","body":"出席、互動、食慾、活動表現與情緒變化，都是社區工作者可以早一步看見的訊號。"}]'::jsonb, 341, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('community', 'service_page', 'scene_cards', '服務情境圖卡', 'json', null, '[{"image":"assets/community-detail-01-exercise-fast.jpg","title":"健康促進小組","body":"用椅上運動、伸展與平衡練習，讓長輩在熟悉社區裡維持活動量。"},{"image":"assets/community-detail-02-meal-fast.jpg","title":"共餐與茶敘陪伴","body":"共餐不只是吃飯，也是在固定時間被看見、被關心、重新建立社交節奏。"},{"image":"assets/community-detail-03-workshop-fast.jpg","title":"認知手作活動","body":"透過手作、桌遊、懷舊與互動設計，讓長輩在活動中保有參與感。"},{"image":"assets/community-detail-04-consult-fast.jpg","title":"家屬資源諮詢","body":"把長照資源、服務轉介與照顧疑問說成家屬聽得懂的下一步。"}]'::jsonb, 342, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('community', 'service_page', 'scenario_cards', '使用情境卡', 'json', null, '[{"title":"長輩還沒失能，但越來越少出門","body":"透過固定活動、共餐與社交互動，讓長輩重新有出門理由，避免功能與情緒慢慢退化。","tag":"重點：預防延緩、社交參與、生活節奏"},{"title":"家屬剛開始接觸長照","body":"據點可以先提供諮詢、課程與資源說明，讓家屬不用一開始就面對複雜制度。","tag":"重點：家屬支持、資源說明、服務轉介"},{"title":"獨居或白天少人互動","body":"共餐、茶敘與團體活動能增加被關心的頻率，也讓社區人員早一步看見狀態變化。","tag":"重點：共餐關懷、情緒支持、日常觀察"},{"title":"失智友善與家屬喘息","body":"以熟悉、安全、低壓活動陪伴長輩，也讓家屬能獲得照顧技巧與情緒支持。","tag":"重點：失智友善、家屬課程、照顧技巧"}]'::jsonb, 343, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('community', 'service_page', 'quality_cards', '品質系統卡', 'json', null, '[{"title":"活動不是越多越好","body":"據點活動要符合長輩體力、興趣與安全狀態，重點是願意持續參與。"},{"title":"出席狀態要被看見","body":"長輩突然缺席、互動下降、食慾改變或情緒低落，都可能是需要關心的訊號。"},{"title":"課程要能帶回生活","body":"跌倒預防、營養、失智友善與用藥安全，都要讓長輩與家屬回家後用得上。"},{"title":"家屬問題要被整理","body":"家屬常問的服務、補助、照顧技巧與轉介問題，會被整理成清楚的下一步。"},{"title":"社區合作要穩定","body":"據點會連結里辦、公部門、醫療與社福資源，讓照顧網絡不只靠單一單位。"},{"title":"轉介要有邏輯","body":"當長輩需求變高時，能從社區活動銜接居家、日照、復能或其他照顧資源。"}]'::jsonb, 344, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('community', 'service_page', 'flow_cards', '服務流程卡', 'json', null, '[{"step":"01","title":"初步諮詢","body":"了解長輩生活狀態、活動能力、交通距離、家屬期待與最想改善的問題。"},{"step":"02","title":"活動媒合","body":"依體力、興趣、認知狀態與交通可近性，建議適合的課程、共餐或健康促進活動。"},{"step":"03","title":"第一次參與","body":"由據點人員協助熟悉環境、活動流程、安全注意事項與同儕互動。"},{"step":"04","title":"固定出席","body":"透過固定活動建立生活節奏，讓長輩有出門理由，也讓家屬看見變化。"},{"step":"05","title":"狀態觀察","body":"觀察出席、食慾、互動、情緒、活動表現與精神狀態，必要時提醒家屬。"},{"step":"06","title":"資源轉介","body":"依照需求銜接居家照顧、日間照顧、護理復能、家屬課程或其他長照資源。"}]'::jsonb, 345, '由目前前台內容匯入，可新增、刪除、排序。'),
  ('community', 'service_page', 'faq_items', '常見問答', 'json', null, '[{"question":"社區據點和日間照顧有什麼不同？","answer":"社區據點多以健康促進、共餐、課程與社區支持為主，日間照顧則是較完整的白天托顧與生活照顧。兩者可以依需求銜接。"},{"question":"長輩一定要失能才能參加嗎？","answer":"不一定。社區據點很適合還能出門、但需要增加活動、社交與預防照顧的長輩。"},{"question":"家屬可以一起參加課程嗎？","answer":"可以。許多據點活動與家屬支持課程，都鼓勵家屬一起理解照顧技巧與資源。"},{"question":"據點活動會固定嗎？","answer":"活動會依據點規劃、服務區域與年度課程調整，建議先聯絡確認最近活動與報名方式。"},{"question":"如果長輩後續需要更多服務怎麼辦？","answer":"據點可以協助家屬理解居家照顧、日間照顧、護理復能與其他長照資源，做下一步銜接。"},{"question":"社區據點適合獨居長輩嗎？","answer":"適合。固定共餐、活動與關懷能增加長輩被看見的頻率，也能讓家屬更安心。"}]'::jsonb, 346, '由目前前台內容匯入，可新增、刪除、排序。')
on conflict (page_slug, template_key, field_key) do update set
  field_label = excluded.field_label,
  field_type = excluded.field_type,
  json_value = excluded.json_value,
  sort_order = excluded.sort_order,
  help_text = excluded.help_text,
  is_enabled = true,
  updated_at = now();
